function ModalHost({modal,close,patient,patients,account,editingPatient,savePatient,go,notify,audit,event,selectedAssessment,selectedXray,setAssessments,setSymptoms,setXrays,setUsers}:{modal:Exclude<ModalName,null>;close:()=>void;patient:Patient;patients:Patient[];account:Account;editingPatient:boolean;savePatient:(f:FormData)=>boolean;go:(p:string)=>void;notify:(s:string)=>void;audit:(a:string,r:string,c?:AuditCategory,p?:string)=>void;event:Audit|null;selectedAssessment:Assessment|null;selectedXray:XrayRecord|null;setAssessments:Dispatch<SetStateAction<Assessment[]>>;setSymptoms:Dispatch<SetStateAction<Symptom[]>>;setXrays:Dispatch<SetStateAction<XrayRecord[]>>;setUsers:Dispatch<SetStateAction<UserRecord[]>>}){
  const [error,setError]=useState(""),[confirmAssessmentDelete,setConfirmAssessmentDelete]=useState(false);function basicSave(e:FormEvent<HTMLFormElement>,message:string,next?:string){e.preventDefault();setTimeout(()=>{audit(message,patient.name,"Patient",patient.id);notify(message);close();if(next)go(next)},500)}
  if(modal==="patient")return <Modal title={editingPatient?"Edit patient details":"Register patient"} onClose={close} wide><form className="modal-form" onSubmit={e=>{e.preventDefault();if(!savePatient(new FormData(e.currentTarget)))setError("Full name, date of birth, phone, address and emergency contact are required.")}}><div className="form-grid"><label>Full name<input name="name" defaultValue={editingPatient?patient.name:""}/></label><label>National ID<input name="nationalId" defaultValue={editingPatient?patient.nationalId:""} placeholder="1 1990 8 1234567 0 12"/></label><label>Gender<select name="gender" defaultValue={editingPatient?patient.gender:"Female"}><option>Female</option><option>Male</option><option>Other</option></select></label><label>Date of birth<input name="dob" type="date" defaultValue={editingPatient?patient.dob:""}/></label><label>Phone<input name="phone" defaultValue={editingPatient?patient.phone:"+250 "}/></label><label>Address<input name="address" defaultValue={editingPatient?patient.address:""}/></label><label>Emergency contact<input name="emergency" defaultValue={editingPatient?patient.emergency:"+250 "}/></label></div><label>Allergies and medical notes<textarea name="notes" defaultValue={editingPatient?patient.notes:""}/></label>{error&&<p className="form-error">{error}</p>}<div className="form-actions"><Button secondary onClick={close}>Cancel</Button><Button type="submit">Save patient</Button></div></form></Modal>;
  if(modal==="assessment")return <Modal title="New dental assessment" onClose={close} wide><form className="modal-form" onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget),p=patients.find(x=>x.id===String(fd.get("patient")))||patient;const a:Assessment={id:`AS-${Date.now().toString().slice(-5)}`,patientId:p.id,patient:p.name,type:String(fd.get("type")),complaint:String(fd.get("complaint")),observations:String(fd.get("observations")),notes:String(fd.get("notes")),dentist:account.name,date:new Date().toISOString().slice(0,10),status:String(fd.get("intent"))==="submit"?"Pending review":"Draft"};setAssessments(x=>[a,...x]);audit("Created assessment",p.name,"Patient",p.id);notify(a.status==="Draft"?"Assessment saved as draft":"Assessment submitted for review");close();go("Assessments")}}><div className="form-grid"><label>Patient<select name="patient" defaultValue={patient.id}>{patients.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label><label>Use template<select name="type"><option>Toothache</option><option>Routine check-up</option><option>Gum problem</option><option>Broken tooth</option><option>Child check-up</option></select></label></div><label>Main complaint<input required name="complaint" placeholder="Describe the main concern"/></label><label>What the dentist sees<textarea required name="observations" placeholder="Document clear clinical observations..."/></label><label>Professional notes<textarea name="notes" placeholder="Additional context..."/></label><label>Attach document<input type="file"/></label><div className="form-actions"><Button secondary onClick={close}>Cancel</Button><Button secondary type="submit" onClick={(e:any)=>{e.currentTarget.form.intent.value="draft"}}>Save draft</Button><input type="hidden" name="intent" defaultValue="submit"/><Button type="submit">Submit for review</Button></div></form></Modal>;
  if(modal==="assessmentDetail"&&selectedAssessment)return <Modal title={`${selectedAssessment.id} · Assessment details`} onClose={close} wide><div className="detail-grid"><div><small>PATIENT</small><b>{selectedAssessment.patient}</b></div><div><small>STATUS</small><Badge>{selectedAssessment.status}</Badge></div><div><small>TYPE</small><b>{selectedAssessment.type}</b></div><div><small>DATE</small><b>{selectedAssessment.date}</b></div><div><small>MAIN COMPLAINT</small><b>{selectedAssessment.complaint}</b></div><div><small>OBSERVATIONS</small><b>{selectedAssessment.observations}</b></div></div><div className="form-actions"><Button secondary onClick={close}>Back</Button><Button secondary onClick={()=>{setAssessments(all=>all.map(a=>a.id===selectedAssessment.id?{...a,status:"Completed"}:a));audit("Completed assessment",selectedAssessment.patient,"Patient",selectedAssessment.patientId);notify("Assessment marked completed");close()}}>Mark completed</Button><Button secondary onClick={()=>setConfirmAssessmentDelete(true)}>Delete</Button></div>{confirmAssessmentDelete&&<ConfirmModal title="Delete assessment" message={`Delete ${selectedAssessment.id}?`} confirmLabel="Delete" onClose={()=>setConfirmAssessmentDelete(false)} onConfirm={()=>{setAssessments(all=>all.filter(a=>a.id!==selectedAssessment.id));audit("Deleted assessment",selectedAssessment.patient,"Patient",selectedAssessment.patientId);close()}}/>}</Modal>;
  if(modal==="symptom")return <Modal title="Add structured symptom" onClose={close}><form className="modal-form" onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget),p=patients.find(x=>x.id===String(fd.get("patient")))||patient;const s:Symptom={id:`SY-${Date.now().toString().slice(-5)}`,patientId:p.id,patient:p.name,category:String(fd.get("category")||"Pain"),tooth:String(fd.get("tooth")),duration:String(fd.get("duration")),severity:Number(fd.get("severity")),triggers:String(fd.get("triggers")),source:String(fd.get("source")),notes:String(fd.get("notes")),date:new Date().toISOString().slice(0,10)};setSymptoms(x=>[s,...x]);audit("Added symptom",p.name,"Patient",p.id);notify("Symptom saved");close();go("Symptoms")}}><label>Patient<select name="patient" defaultValue={patient.id}>{patients.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label><fieldset><legend>Category</legend><div className="chip-row">{["Pain","Swelling","Bleeding","Sensitivity","Bad breath","Loose tooth","Other"].map(x=><label key={x}><input type="radio" name="category" value={x} defaultChecked={x==="Pain"}/><span>{x}</span></label>)}</div></fieldset><div className="form-grid"><label>Tooth number / location<input name="tooth" required placeholder="e.g. 26"/></label><label>Duration<input name="duration" required placeholder="e.g. 3 days"/></label></div><label>Severity: 1–10<input name="severity" type="range" min="1" max="10" defaultValue="6"/></label><label>Triggers<select name="triggers"><option>Cold</option><option>Hot</option><option>Sweet</option><option>Chewing</option><option>At night</option><option>No trigger</option></select></label><label>Source<select name="source"><option>Patient-reported</option><option>Clinically observed</option></select></label><label>Notes<textarea name="notes"/></label><div className="form-actions"><Button secondary onClick={close}>Cancel</Button><Button type="submit">Save symptom</Button></div></form></Modal>;
  if(modal==="bulkSymptoms")return <Modal title="Bulk add symptoms" onClose={close} wide><form className="modal-form" onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget),p=patients.find(x=>x.id===String(fd.get("patient")))||patient;["Pain","Sensitivity","Swelling"].forEach((cat,i)=>setSymptoms(x=>[{id:`SY-${Date.now()+i}`,patientId:p.id,patient:p.name,category:cat,tooth:String(26+i*5),duration:"3 days",severity:4+i*2,triggers:"Cold",source:"Patient-reported",notes:"Bulk entry",date:new Date().toISOString().slice(0,10)},...x]));audit("Bulk added symptoms",p.name,"Patient",p.id);notify("3 symptoms saved");close()}}><label>Patient<select name="patient" defaultValue={patient.id}>{patients.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label>{["Pain","Sensitivity","Swelling"].map((x,i)=><div className="bulk-row" key={x}><input defaultValue={x}/><input defaultValue={26+i*5}/><input type="number" defaultValue={4+i*2}/><button type="button" onClick={e=>(e.currentTarget.parentElement!.style.display="none")}><X size={14}/></button></div>)}<div className="form-actions"><Button secondary onClick={close}>Cancel</Button><Button type="submit">Save all</Button></div></form></Modal>;
  if(modal==="xray")return <XrayUpload close={close} go={go} notify={notify} audit={audit} patient={patient} patients={patients} account={account} setXrays={setXrays}/>;
  if(modal==="viewer"&&selectedXray)return <XrayViewer close={close} go={go} notify={notify} xray={selectedXray} setXrays={setXrays}/>;
  if(modal==="reject")return <Modal title="Reject clinical recommendation" onClose={close}><form className="modal-form" onSubmit={e=>basicSave(e,"Recommendation rejected")}><label>Reason for rejection<textarea required placeholder="A reason is required for the audit record."/></label><div className="form-actions"><Button secondary onClick={close}>Cancel</Button><Button type="submit">Reject recommendation</Button></div></form></Modal>;
  if(modal==="forgot")return <Modal title="Reset password" onClose={close}><form className="modal-form" onSubmit={e=>{e.preventDefault();notify("Password reset link sent");close()}}><label>Email address<input required type="email" placeholder="professional@clinic.com"/></label><div className="form-actions"><Button secondary onClick={close}>Cancel</Button><Button type="submit">Send reset link</Button></div></form></Modal>;
  if(modal==="event"&&event)return <Modal title="Audit event details" onClose={close}><div className="detail-grid"><div><small>WHO</small><b>{event.user}</b></div><div><small>WHAT</small><b>{event.action}</b></div><div><small>CATEGORY</small><b>{event.category}</b></div><div><small>RECORD</small><b>{event.record}</b></div><div><small>WHEN</small><b>{event.date} · {event.time}</b></div><div><small>PATIENT ID</small><b>{event.patientId||"Not linked"}</b></div></div><div className="form-actions"><Button onClick={close}>Close</Button></div></Modal>;
  if(modal==="user")return <Modal title="Add authorized user" onClose={close}><form className="modal-form" onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const u:UserRecord={id:`US-${Date.now()}`,name:String(fd.get("name")),email:String(fd.get("email")),phone:String(fd.get("phone")),role:String(fd.get("role")) as Role,status:"Active"};setUsers(x=>[u,...x]);audit("Added authorized user",u.name,"System");notify("User saved");close()}}><label>Full name<input name="name" required placeholder="Staff member name"/></label><label>Email address<input name="email" required type="email" placeholder="name@oridental.rw"/></label><label>Phone<input name="phone" required defaultValue="+250 "/></label><label>Role<select name="role"><option>Dental Professional</option><option>Clinic Staff</option><option>Administrator</option></select></label><div className="form-actions"><Button secondary onClick={close}>Cancel</Button><Button type="submit">Save user</Button></div></form></Modal>;
  return <Modal title="My profile" onClose={close}><div className="detail-grid"><div><small>NAME</small><b>{account.name}</b></div><div><small>ROLE</small><b>{account.role}</b></div><div><small>EMAIL</small><b>{account.email}</b></div><div><small>CLINIC</small><b>ORI Dental Clinic</b></div></div><form className="modal-form" onSubmit={e=>{e.preventDefault();notify("Password changed");close()}}><h3>Change password</h3><label>Current password<input type="password" required/></label><label>New password<input type="password" required minLength={8}/></label><label>Confirm new password<input type="password" required minLength={8}/></label><div className="form-actions"><Button secondary onClick={close}>Cancel</Button><Button type="submit">Change password</Button></div></form></Modal>;
}

function XrayUpload({close,go,notify,audit,patient,patients,account,setXrays}:{close:()=>void;go:(p:string)=>void;notify:(s:string)=>void;audit:(a:string,r:string,c?:AuditCategory,p?:string)=>void;patient:Patient;patients:Patient[];account:Account;setXrays:Dispatch<SetStateAction<XrayRecord[]>>}){const [file,setFile]=useState<File|null>(null),[preview,setPreview]=useState("");function selectFile(next?:File){if(!next)return;setFile(next);const reader=new FileReader();reader.onload=()=>setPreview(String(reader.result||""));reader.readAsDataURL(next)}return <Modal title="Upload dental X-ray" onClose={close}><form className="modal-form" onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget),p=patients.find(x=>x.id===String(fd.get("patient")))||patient;if(!file){notify("Choose an X-ray image");return}const x:XrayRecord={id:`XR-${Date.now().toString().slice(-5)}`,patientId:p.id,patient:p.name,type:String(fd.get("type")),region:String(fd.get("region")),date:String(fd.get("date")),uploadedBy:account.name,fileName:file.name,preview,markers:[]};setXrays(all=>[x,...all]);audit("Uploaded X-ray",p.name,"Patient",p.id);notify("X-ray uploaded and linked");close();go("Dental X-Rays")}}><div className="drop-zone interactive-drop" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();selectFile(e.dataTransfer.files[0])}}>{preview?<img src={preview} alt="X-ray preview"/>:<Upload/>}<b>{file?.name||"Drop X-ray here"}</b><span>or browse an image file</span><input id="xray-file" type="file" accept="image/*" onChange={e=>selectFile(e.target.files?.[0])}/><label htmlFor="xray-file" className="btn-secondary">Browse files</label></div><label>Patient<select name="patient" defaultValue={patient.id}>{patients.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label><label>Image type<select name="type"><option>Panoramic</option><option>Bitewing</option><option>Periapical</option></select></label><label>Tooth region<input name="region" required placeholder="e.g. Left lower jaw"/></label><label>Date<input name="date" type="date" required defaultValue={new Date().toISOString().slice(0,10)}/></label>{file&&<div className="upload-metadata"><b>Ready to upload</b><span>{file.name} · {(file.size/1024).toFixed(1)} KB</span></div>}<div className="form-actions"><Button secondary onClick={close}>Cancel</Button><Button type="submit">Upload X-ray</Button></div></form></Modal>}

function XrayViewer({close,go,notify,xray,setXrays}:{close:()=>void;go:(p:string)=>void;notify:(s:string)=>void;xray:XrayRecord;setXrays:Dispatch<SetStateAction<XrayRecord[]>>}){const [zoom,setZoom]=useState(1),[brightness,setBrightness]=useState(100),[contrast,setContrast]=useState(110),[marks,setMarks]=useState<XrayMarker[]>(xray.markers),[draft,setDraft]=useState<{x:number;y:number;text:string}|null>(null),[editing,setEditing]=useState<XrayMarker|null>(null);function save(){setXrays(all=>all.map(item=>item.id===xray.id?{...item,markers:marks}:item));notify("X-ray note markers saved")}return <Modal title={`${xray.type} X-ray viewer`} onClose={close} wide><div className="viewer-tools"><button onClick={()=>setZoom(Math.max(.6,zoom-.1))}><ZoomOut/></button><button onClick={()=>setZoom(Math.min(2,zoom+.1))}><ZoomIn/></button><button onClick={()=>setMarks([])}>Clear markers</button><span>Click the image to add a note marker</span></div><div className="modal-xray marker-canvas" onClick={e=>{const rect=e.currentTarget.getBoundingClientRect();setDraft({x:(e.clientX-rect.left)/rect.width*100,y:(e.clientY-rect.top)/rect.height*100,text:""})}}><div style={{transform:`scale(${zoom})`,filter:`brightness(${brightness}%) contrast(${contrast}%)`}}>{xray.preview?<img src={xray.preview} alt={`${xray.type} X-ray`}/>:<DentalXray className="xray-svg"/>}</div>{marks.map(mark=><button className="note-marker" style={{left:`${mark.x}%`,top:`${mark.y}%`}} key={mark.id} onClick={e=>{e.stopPropagation();setEditing(mark)}} title={mark.text}>{marks.indexOf(mark)+1}</button>)}</div><div className="xray-sliders"><label>Brightness <input type="range" min="50" max="150" value={brightness} onChange={e=>setBrightness(Number(e.target.value))}/></label><label>Contrast <input type="range" min="50" max="180" value={contrast} onChange={e=>setContrast(Number(e.target.value))}/></label></div><div className="marker-list">{marks.map((mark,i)=><article key={mark.id}><b>Marker {i+1}</b><span>{mark.text}</span><button onClick={()=>setEditing(mark)}>Edit</button><button onClick={()=>setMarks(all=>all.filter(m=>m.id!==mark.id))}>Delete</button></article>)}</div><div className="form-actions"><Button secondary onClick={()=>{setZoom(1);setBrightness(100);setContrast(110)}}>Reset view</Button><Button secondary onClick={save}>Save markers</Button><Button secondary onClick={close}>Close</Button><Button onClick={()=>{save();close();go("AI X-Ray Review")}}>Review with AI →</Button></div>{draft&&<Modal title="Add note marker" onClose={()=>setDraft(null)}><form className="modal-form" onSubmit={e=>{e.preventDefault();const text=String(new FormData(e.currentTarget).get("text"));setMarks(all=>[...all,{id:`MARK-${Date.now()}`,x:draft.x,y:draft.y,text}]);setDraft(null)}}><label>Marker note<input name="text" autoFocus required placeholder="Describe this area"/></label><div className="form-actions"><Button secondary onClick={()=>setDraft(null)}>Cancel</Button><Button type="submit">Add marker</Button></div></form></Modal>}{editing&&<Modal title="Edit note marker" onClose={()=>setEditing(null)}><form className="modal-form" onSubmit={e=>{e.preventDefault();const text=String(new FormData(e.currentTarget).get("text"));setMarks(all=>all.map(m=>m.id===editing.id?{...m,text}:m));setEditing(null)}}><label>Marker note<input name="text" autoFocus required defaultValue={editing.text}/></label><div className="form-actions"><Button secondary onClick={()=>setEditing(null)}>Cancel</Button><Button type="submit">Save note</Button></div></form></Modal>}</Modal>}

export default function Prototype(){const [accounts,setAccounts]=useState(demoAccounts),[account,setAccount]=useState<Account|null>(null),[forgot,setForgot]=useState(false),[publicPage,setPublicPage]=useState<"landing"|"signin"|"create">("landing");function createAccount(newAccount:Account){setAccounts(a=>[...a,newAccount]);setAccount(newAccount)}if(account)return <AppShell account={account} onLogout={()=>{setAccount(null);setPublicPage("signin")}}/>;if(publicPage==="landing")return <Landing onSignIn={()=>setPublicPage("signin")} onCreate={()=>setPublicPage("create")}/>;return <><Login key={publicPage} startCreating={publicPage==="create"} accounts={accounts} onLogin={setAccount} onCreate={createAccount} onForgot={()=>setForgot(true)}/>{forgot&&<Modal title="Reset password" onClose={()=>setForgot(false)}><form className="modal-form" onSubmit={e=>{e.preventDefault();setForgot(false)}}><label>Email address<input required type="email"/></label><div className="form-actions"><Button secondary onClick={()=>setForgot(false)}>Cancel</Button><Button type="submit">Send reset link</Button></div></form></Modal>}</>}
